∀ (n B : ℕ) (ok : ℕ → Bool) (value : ℕ → ℕ),
  have result := ExternalO3OptimizationCode.foldTo n B fun i best => if ok i = true then min best (value i) else best;
  result ≤ B ∧ (∀ i < n, ok i = true → result ≤ value i) ∧ (result = B ∨ ∃ i < n, ok i = true ∧ result = value i)

∀ (p : ExternalO3OptimizationCode.Input) (mask : ℕ),
  ExternalO3OptimizationAlgorithm.maskSubset p mask =
    {a | ExternalO3OptimizationCode.deleted mask ↑↑((ExternalO3OptimizationEdgeCode.edgeCodeEquiv p) a) = true}

∀ {n : ℕ} (α : Fin (n + 1) → Type u_1),
  Fin.consEquiv α =
    { toFun := fun f => Fin.cons f.1 f.2, invFun := fun f => (f 0, Fin.tail f), left_inv := ⋯, right_inv := ⋯ }
